// Who shares the rota, filled in when the template is added. The turn starts with them and each pass moves it on.
const WHO = {{who}};
const INK = '#121a2e';
const LIME = { light: '#d8f36b', dark: '#263a1c' };
const WORDS = { light: INK, dark: '#eaf6a8' };
const KEY = { light: INK, dark: '#d8f36b' };
const KEY_WORDS = { light: '#d8f36b', dark: '#1f260c' };
const BIN = 'M4 6.5h16M9.5 6.5V4h5v2.5M6 6.5l1 14h10l1-14';

// The key's fill sits twice: solid in the backdrop, which tinted and clear mode remove, and faint in the tree.
// So in full color it reads as one solid key, and in tinted mode its words still show on the faint one.
function key(u, ghost) {
  return { type: 'zstack', padding: { leading: 15 * u, bottom: 15 * u },
    frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'bottomLeading' },
    children: [
      { type: ghost ? 'zstack' : 'button', action: ghost ? null : 'pass', children: [
        { type: 'zstack', padding: { vertical: 7 * u, horizontal: 11 * u },
          background: { type: 'rect', cornerRadius: 10 * u, fill: ghost ? KEY : { light: '#121a2e40', dark: '#d8f36b40' } },
          children: [
            { type: 'text', value: 'Pass it on', size: 12.5 * u, weight: 'bold', color: KEY_WORDS,
              opacity: ghost ? 0 : 1 },
          ] } ] },
    ] };
}

function render(ctx) {
  // Sizes are in units of `u`, 1/170 of the widget's height. Bricolage's line is 1.2 times its size, so the gaps
  // around the name are 0.1 of its size shorter, as if its line were its size.
  const u = ctx.height / 170;
  const mine = ctx.data.passes % 2 === 1;

  return {
    type: 'zstack', align: 'topLeading',
    frame: { maxWidth: 'infinity', maxHeight: 'infinity' },
    widgetBackground: { type: 'zstack', frame: { maxWidth: 'infinity', maxHeight: 'infinity' }, background: LIME,
      children: [key(u, true)] },
    children: [
      { type: 'vstack', align: 'leading', spacing: 0,
        padding: { top: 15 * u, leading: 16 * u, trailing: 16 * u },
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' },
        children: [
          { type: 'hstack', spacing: 5 * u, frame: { height: 16 * u }, children: [
            { type: 'path', d: BIN, viewBox: [0, 0, 24, 24], frame: { width: 15 * u, height: 15 * u },
              stroke: { color: WORDS, width: 2.4 * 15 * u / 24, cap: 'round' } },
            { type: 'text', value: 'Bins night', size: 13 * u, weight: 'bold', color: WORDS, lineLimit: 1 } ] },
          { type: 'text', value: mine ? 'You' : WHO, fontName: 'Bricolage Grotesque Display', size: 36 * u,
            kerning: -1.08 * u, color: WORDS, accent: true, lineLimit: 1, minScale: 0.3, padding: { top: 4.4 * u } },
          { type: 'text', value: mine ? 'your turn tonight' : 'up tonight', size: 12.5 * u, weight: 'semibold',
            color: WORDS, opacity: 0.8, lineLimit: 1, minScale: 0.8, padding: { top: 1.4 * u } },
        ] },
      key(u, false),
    ],
  };
}
